const gcipCloudFunctions = require('gcip-cloud-functions');

const authClient = new gcipCloudFunctions.Auth();

/** Admin user domains. */
const ADMIN_DOMAIN = '@admin.example.com';
/** Placeholder image. */
const PLACEHOLDER_IMAGE = 'https://www.gstatic.com/images/branding/product/1x/play_apps_48dp.png';
/** Placeholder display name. */
const PLACEHOLDER_NAME = 'Guest';
/** Blocked domain. */
const BLOCKED_DOMAIN = '@evil.com';

/**
 * Returns whether the user is an admin or not.
 * @param {*} user The user record to check.
 * @return {boolean} Whether the user is an admin or not.
 */
const isAdmin = (user) => {
  return !!(user.email && user.email.indexOf(ADMIN_DOMAIN) !== -1 && user.emailVerified);
};


/**
 * Returns whether the user is allowed or not.
 * @param {*} user The user record to check.
 * @return {boolean} Whether the user is allowed or not.
 */
const isAllowedUser = (user) => {
  // Block users with either no email or with blocked domains.
  return !!user.email && user.email.indexOf(BLOCKED_DOMAIN) === -1;
};


// Http trigger before user signs up.
exports.beforeCreate = authClient.functions().beforeCreateHandler((user, context) => {
  // Get employee ID if available.
  const eid = (context.credential &&
      context.credential.claims &&
      context.credential.claims.employeeid) || 'unknown';
  if (isAllowedUser(user)) {
    let response = {
      // Set employee ID as custom claim, if available.
      customClaims: {
        eid,
      },
    };
    if (context.eventType.indexOf('github') !== -1) {
      // Consider GitHub users verified.
      response.emailVerified = true;
    }
    return response;
  } else {
    throw new gcipCloudFunctions.https.HttpsError('invalid-argument', `Unauthorized email "${user.email}"`);
  }
});


// Http trigger before user signs in.
exports.beforeSignIn = authClient.functions().beforeSignInHandler((user, context) => {
  // Return any additional claims that need to be set on the user.
  return {
    // Format displayNames. Capitalize first letter or set default name if not available.
    displayName: user.displayName ?
        user.displayName.charAt(0).toUpperCase() + user.displayName.substring(1) : PLACEHOLDER_NAME,
    // User placeholder image if user doesn't have profile picture.
    photoURL: user.photoURL || PLACEHOLDER_IMAGE,
    sessionClaims: {
      admin: isAdmin(user),
      // Embed IP address in the token claims.
      ip: context.ipAddress,
    },
  };
});
